import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";

import { curvePrice, formatPrice, liveSupply, marketCap, type ExactPrice } from "@interest-protocol/blast-sdk/launchpad";

import { parseMarketEconomics, type MarketEconomics } from "./v1.ts";

/**
 * AC-125: blast-infra's display economics, recomputed from each `/v1` answer's
 * `inputs` through the canonical SDK's exact functions, must equal what
 * blast-infra published, to the digit.
 *
 * The fixture's engine cases are regenerated by apps/web/test/scripts/capture-v1-economics.ts
 * (its header has the engine command).
 */

type Case = { source: string } & Record<string, unknown>;
const fixture = JSON.parse(
  readFileSync(new URL("../../../test/fixtures/modules/launchpad-contract/fixtures/v1-market-economics.json", import.meta.url), "utf8"),
) as { cases: Case[] };

const Q128 = 1n << 128n;

/**
 * The exact price of a summary's inputs: the SDK's curve price, or for a
 * venue pool the documented Q64.64 ratio (`s²/2^128`, inverted when the meme
 * is coin B), which the SDK has no reader for; both are formatted and
 * multiplied by the SDK.
 */
function exactPrice(economics: MarketEconomics): ExactPrice | null {
  const inputs = economics.inputs;
  if (economics.venue === "blast_curve") {
    if (inputs.memeReserve === null) return null;
    return curvePrice({
      virtualQuote: inputs.virtualQuote as bigint,
      realQuoteReserve: inputs.quoteReserve as bigint,
      memeReserve: inputs.memeReserve,
    });
  }
  const squared = (inputs.sqrtPriceX64 as bigint) ** 2n;
  if (squared === 0n) return null;
  return inputs.memeIsCoinA ? { numerator: squared, denominator: Q128 } : { numerator: Q128, denominator: squared };
}

/** The fields whose published value the SDK does not reproduce from the inputs. */
function mismatches(value: Record<string, unknown>): string[] {
  const economics = parseMarketEconomics(value);
  const price = exactPrice(economics);
  const supply = liveSupply(economics.inputs);
  const differ: string[] = [];
  if ((price === null ? null : formatPrice(price)) !== economics.price) differ.push("price");
  if (marketCap(supply, price) !== economics.marketCap) differ.push("market_cap");
  if (economics.supply !== null && supply !== economics.supply) differ.push("supply");
  return differ;
}

test("every /v1 summary and trade's price, market cap and supply are the SDK's, from its inputs", () => {
  const venues = new Set<string>();
  for (const { source, ...value } of fixture.cases) {
    assert.deepEqual(mismatches(value), [], source);
    venues.add(String(value.venue));
  }
  assert.ok(fixture.cases.length >= 100, `${fixture.cases.length} cases`);
  assert.deepEqual([...venues].sort(), ["blast_curve", "cetus"]);
});

test("any published value one digit or atom off fails the contract", () => {
  /** The same canonical string with its last digit changed. */
  const lastDigitOff = (decimal: string) =>
    decimal.slice(0, -1) + (decimal.endsWith("9") ? "8" : String(Number(decimal.at(-1)) + 1));
  const bump = (atoms: unknown) => (BigInt(String(atoms)) + 1n).toString();
  const priced = fixture.cases.filter((item) => item.price !== null && item.market_cap !== null);
  assert.ok(priced.length > 0);
  for (const { source, ...value } of priced) {
    const inputs = value.inputs as Record<string, unknown>;
    for (const [expected, tampered] of [
      ["price", { ...value, price: lastDigitOff(String(value.price)) }],
      ["market_cap", { ...value, market_cap: bump(value.market_cap) }],
      // One atom more of the input the price comes from.
      [
        "price",
        value.venue === "blast_curve"
          ? { ...value, inputs: { ...inputs, virtual_quote: bump(inputs.virtual_quote) } }
          : { ...value, inputs: { ...inputs, sqrt_price_x64: bump(inputs.sqrt_price_x64) } },
      ],
    ] as const) {
      assert.ok(mismatches(tampered).includes(expected), `${source}: a changed ${expected} went unnoticed`);
    }
  }
});
